UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Reperfusion Strategy","body":"**Anticoagulation** — start immediately:\n• [UFH](#/drug/ufh/pe) — no bolus if thrombolysis imminent; low-dose infusion ≤500 U/hr\n• UFH preferred (can be stopped if hemorrhage)\n\n**Systemic thrombolysis** — only intervention with mortality benefit data (foundational massive/submassive PE management).\n\n**Dosing options:**\n• Standard: [Alteplase](#/drug/alteplase/pulmonary) **100 mg IV over 2h** (0.6 mg/kg up to 50 mg over first 15 min, remainder over next 1h45min)\n• Reduced-dose: **50 mg IV** over 2h (emerging — less bleeding, equivalent efficacy; HI-PEITHO 2026)\n• Cardiac arrest: **50 mg IV bolus** + sustained CPR\n• **Tenecteplase (alternative, off-label):** weight-based single bolus — 30 mg (<60 kg), 35 mg (60–69), 40 mg (70–79), 45 mg (80–89), 50 mg (≥90 kg). Single bolus advantage; mortality similar to alteplase.\n\n**2026 update:** Mechanical thrombectomy and catheter-directed lysis are both reasonable for stable-enough patients — the 2026 AHA/ACC guideline does NOT prefer one over the other (Class 2b); choose based on operator experience, clot location, and bleeding risk (PEERLESS showed no mortality or major-bleeding difference). STRATIFY (2026) shows peripheral 20 mg tPA over 6h equivalent to CDT.","citation":[1,2,3,6,7,8,11,12],"options":[{"label":"Systemic Thrombolysis","description":"No absolute contraindications — proceed with alteplase","next":"pe-anticoag-selection"},{"label":"Thrombolysis Contraindicated","description":"Recent surgery, active bleeding, prior ICH, etc.","next":"pe-advanced-interventions","urgency":"urgent"},{"label":"Refractory Shock / Arrest","description":"Failed thrombolysis or deteriorating despite treatment","next":"pe-advanced-interventions","urgency":"critical"}],"treatment":{"firstLine":{"drug":"Alteplase","dose":"100 mg (or 50 mg reduced-dose; 50 mg IV push if cardiac arrest)","route":"IV","frequency":"Over 2 hours (0.6 mg/kg up to 50 mg over first 15 min, remainder over next 1h45min); flat 50 mg IV push if cardiac arrest","duration":"Single dose","notes":"Cardiac arrest: 50 mg IV bolus + CPR; avoid concurrent heparin bolus. Tenecteplase alternative: weight-based 30–50 mg single bolus."},"alternative":{"drug":"UFH (low-dose)","dose":"≤500 units/hr infusion (no bolus)","route":"IV","frequency":"Continuous","duration":"Until reperfusion achieved","notes":"Give alteplase BEFORE heparin to reduce bleeding risk"},"monitoring":"Hemodynamics; fibrinogen if reduced-dose protocol; bleeding signs"},"calculatorLinks":[{"id":"alteplase-pe-dosing","label":"Alteplase Dosing"}],"summary":"UFH (no bolus) + alteplase 100 mg over 2h (or 50 mg reduced-dose); cardiac arrest = 50 mg bolus + CPR","safetyLevel":"critical"}'::jsonb
WHERE id = 'pe-crashing-reperfusion' AND tree_id = 'pe-treatment';

-- Node: pe-intermediate-high (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"High-Risk Category C","body":"Multiple risk factors: RV dysfunction + elevated biomarkers + lactate elevation.\n\n**Management:**\n• [UFH](#/drug/ufh/pe) preferred (allows rapid escalation)\n• **ICU monitoring** — watch for decompensation\n• **Activate PERT** for multidisciplinary planning\n\n**2026 update:** For stable Category C patients, **mechanical thrombectomy and CDT are both reasonable** — the 2026 AHA/ACC guideline does not prefer one over the other (Class 2b). PEERLESS showed lower ICU admission and deterioration with thrombectomy but no mortality or major-bleeding difference; individualize by operator experience, clot location, and bleeding risk.\n\n**If decompensation occurs:**\n• Reduced-dose alteplase 25-50 mg IV over 2-6h\n• Or mechanical thrombectomy if PERT/IR available","citation":[1,6,8],"options":[{"label":"Continue Anticoagulation + Monitoring","description":"Remains hemodynamically stable","next":"pe-anticoag-selection"},{"label":"Advanced Intervention","description":"Decompensating or high clot burden — consider mechanical thrombectomy","next":"pe-advanced-interventions","urgency":"urgent"}],"treatment":{"firstLine":{"drug":"UFH","dose":"80 units/kg bolus, then 18 units/kg/hr","route":"IV","frequency":"Continuous","duration":"Until oral anticoagulation therapeutic","notes":"Preferred over LMWH — allows rapid escalation to thrombolysis"},"alternative":{"drug":"Reduced-dose Alteplase (rescue)","dose":"25-50 mg","route":"IV","frequency":"Over 2-6 hours","duration":"Single dose","notes":"For decompensation; monitor fibrinogen, hold if <150 mg/dL"},"monitoring":"Hemodynamics q1-2h; troponin/lactate q6h; fibrinogen if lytics given"},"summary":"UFH + ICU monitoring; PERT activation; mechanical thrombectomy OR CDT if intervention needed — both reasonable, individualize (PEERLESS: no mortality/bleeding difference)","safetyLevel":"warning"}'::jsonb
