UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Advanced Interventions","body":"**2026 update:** For patients stable enough for procedure, **mechanical thrombectomy and catheter-directed lysis are both reasonable options** — the 2026 AHA/ACC guideline does NOT prefer one over the other (Class 2b). Choose based on operator experience, clot location, urgency, and bleeding risk.\n\n**PEERLESS trial results (N=550):**\n• Mechanical thrombectomy vs CDT for intermediate-risk PE\n• Lower clinical deterioration: 1.8% vs 5.4%\n• Lower ICU admission: 41.6% vs 98.6%\n• Lower 30-day readmission: 3.2% vs 7.9%\n• No difference in mortality or major bleeding\n\n**Options by clinical scenario:**","citation":[6,8],"options":[{"label":"Mechanical Thrombectomy","description":"Preferred for intermediate-risk; patient stable for transport to IR","next":"pe-mechanical-thrombectomy"},{"label":"Catheter-Directed Lysis (CDT)","description":"Alternative if mechanical not available; lower systemic bleeding than full-dose","next":"pe-cdt"},{"label":"VA-ECMO","description":"Refractory shock despite treatment, or cardiac arrest from PE","next":"pe-ecmo","urgency":"critical"},{"label":"Surgical Embolectomy","description":"Refractory cases, contraindications to other approaches, or cardiothoracic available","next":"pe-surgery"}],"summary":"Mechanical thrombectomy and CDT both reasonable — guideline does not prefer either (PEERLESS: no mortality/bleeding difference); VA-ECMO for refractory shock; surgical embolectomy as backup","safetyLevel":"warning"}'::jsonb
